import {matchTeacher} from './teacher-match.mjs';
import{meetingStatus}from'./meeting-status.mjs';
export const validDate=value=>{if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const d=new Date(value+'T12:00:00Z');return !isNaN(d)&&d.toISOString().slice(0,10)===value};
const text=(v,max,label,required=false)=>{if(typeof v!=='string')v='';v=v.trim();if((required&&!v)||v.length>max)throw Error(`${label}: ${required?'enter text, up to':'maximum'} ${max} characters.`);return v};
export function validateReport(input){
 const status=input.status||'held';if(!['held','missed','cancelled','postponed'].includes(status))throw Error('Choose a valid meeting status.');
 let participants=Number(input.participants);if(status!=='held')participants=0;if((status==='held'&&(input.participants===''||input.participants===null||input.participants===undefined))||!Number.isInteger(participants)||participants<0||participants>100000)throw Error('Enter a participant count from 0 to 100000.');
 const nameEntry=input.teacherEntryMode==='name';
 const typedTeacher=nameEntry?text(input.actualTeacherName,120,'Teacher who taught',true):'';
 const scheduledName=nameEntry?text(input.assignedTeacherName,120,'Assigned teacher name'):'';
 const teacherOutcome=nameEntry?(scheduledName?(matchTeacher(typedTeacher,[{id:'scheduled',name:scheduledName}]).status==='matched'?'assigned':'replacement'):'unknown'):input.teacherOutcome||'unknown';if(!['assigned','replacement','not_taught','unknown'].includes(teacherOutcome))throw Error('Choose who taught the gubae.');if(status!=='held'&&['assigned','replacement'].includes(teacherOutcome))throw Error('A teacher can only be recorded as having taught when the gubae was held.');
 const assignedTeacherName=text(input.assignedTeacherName,120,'Assigned teacher name',teacherOutcome!=='unknown');
 const actualTeacherName=nameEntry?typedTeacher:teacherOutcome==='assigned'?assignedTeacherName:teacherOutcome==='replacement'?text(input.actualTeacherName,120,'Replacement teacher name',true):'';
 if(!nameEntry&&teacherOutcome==='replacement'&&assignedTeacherName.normalize('NFKC').toLowerCase()===actualTeacherName.normalize('NFKC').toLowerCase())throw Error('The replacement must be a different teacher.');
 const teacherChangeReason=['replacement','not_taught'].includes(teacherOutcome)?text(input.teacherChangeReason,2000,'Reason assigned teacher did not teach',!nameEntry):'';
 const taught=status==='held'&&teacherOutcome!=='not_taught';const teachingRating=taught?Number(input.teachingRating):null;if(taught&&(!Number.isInteger(teachingRating)||teachingRating<1||teachingRating>5))throw Error('Rate the teaching from 1 to 5.');
 return{organizerName:text(input.organizerName,120,'Organizer name',true),status,participants,teachingRating,teachingFeedback:taught?text(input.teachingFeedback,4000,'Teaching feedback',!nameEntry):'',comments:text(input.comments,6000,'Comments'),missedReason:status==='held'?'':text(input.missedReason,2000,'Why was the gubae not held?',true),teacherOutcome,assignedTeacherName,actualTeacherName,teacherChangeReason};
}
export function dateRange({month,from,to}){if(month){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month))throw Error('Choose a valid month.');from=month+'-01';const d=new Date(from+'T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+1);d.setUTCDate(0);to=d.toISOString().slice(0,10);}if(!validDate(from)||!validDate(to)||from>to||new Date(to)-new Date(from)>366*86400000)throw Error('Choose a date range of up to one year.');return{from,to};}
export function monthlyReport(meetings,reports,range,today,teachers=[]){
 const{from,to}=dateRange(range),byId=new Map(reports.map(r=>[r.meetingId||r.id,r])),teacherNames=new Map(teachers.map(t=>[t.id,t.name]));
 const rows=meetings.filter(m=>m.date>=from&&m.date<=to).sort((a,b)=>a.date.localeCompare(b.date)||String(a.id).localeCompare(String(b.id),undefined,{numeric:true})).map(m=>{const r=byId.get(m.id);return{status:meetingStatus(m,r,new Date(today+'T00:00:00+04:00')),missedReason:m.outcome?m.outcomeReason||'':r?.missedReason||'',meetingId:m.id,topic:m.topic,date:m.date,startTime:m.startTime||'21:00',reportStatus:r?'Submitted':m.date>today?'Not yet due':'Missing',assignedTeacherName:r?r.assignedTeacherName||'Not recorded':teacherNames.get(m.teacherId)||m.scheduledTeacherName||'Unassigned',actualTeacherName:r?.actualTeacherName||(r?.teacherOutcome==='assigned'?r.assignedTeacherName:'')||'',report:r||null};});
 const submitted=rows.filter(r=>r.report),held=rows.filter(r=>r.status==='held'),missed=rows.filter(r=>['missed','cancelled','postponed'].includes(r.status)),due=rows.filter(r=>r.date<=today),reportedDue=due.filter(r=>r.report),rated=held.filter(r=>Number.isInteger(r.report?.teachingRating)&&r.report.teachingRating>=1&&r.report.teachingRating<=5);
 const attended=held.filter(r=>r.report?.status==='held'&&Number.isInteger(r.report.participants)),totalParticipants=attended.reduce((n,r)=>n+r.report.participants,0),teacherChanges=rows.filter(r=>['replacement','not_taught'].includes(r.report?.teacherOutcome));
 const reasons=new Map();for(const r of missed){const reason=r.missedReason?.trim()||'Reason not recorded',key=reason.toLowerCase();const entry=reasons.get(key)||{reason,count:0};entry.count++;reasons.set(key,entry);}
 return{from,to,generatedAt:new Date().toISOString(),summary:{scheduled:rows.length,submitted:submitted.length,missing:due.length-reportedDue.length,upcoming:rows.filter(r=>r.status==='upcoming').length,held:held.length,missed:missed.length,cancelled:rows.filter(r=>r.status==='cancelled').length,postponed:rows.filter(r=>r.status==='postponed').length,totalParticipants,averageParticipants:attended.length?Math.round(totalParticipants/attended.length*100)/100:null,averageTeachingRating:rated.length?Math.round(rated.reduce((n,r)=>n+r.report.teachingRating,0)/rated.length*100)/100:null,coverage:due.length?Math.round(reportedDue.length/due.length*100):null,teacherReplacements:teacherChanges.filter(r=>r.report.teacherOutcome==='replacement').length,assignedDidNotTeach:teacherChanges.length,teacherNotRecorded:held.filter(r=>!r.report?.teacherOutcome||r.report.teacherOutcome==='unknown').length},missedReasons:[...reasons.values()].sort((a,b)=>b.count-a.count),teacherChanges,rows};
}
export const csvCell=value=>{let s=String(value??'');if(/^[\s]*[=+@\-]/.test(s)||/^[\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};
export function reportCsv(report){const lines=[['Mahber','Meeting date','Dubai start time','Report status','Meeting status','Participants','Why not held','Assigned teacher','Who taught','Teacher outcome','Why assigned teacher did not teach','Teaching rating (1-5)','Organizer','Teaching feedback','Comments','Last updated']];for(const r of report.rows){const p=r.report;lines.push([r.topic,r.date,r.startTime,r.reportStatus,r.status,r.status==='held'?p?.participants:'',r.status!=='held'?r.missedReason||'':'',r.assignedTeacherName,r.actualTeacherName,p?.teacherOutcome||'unknown',p?.teacherChangeReason,p?.teachingRating,p?.organizerName,p?.teachingFeedback,p?.comments,p?.updatedAt]);}return '\ufeff'+lines.map(row=>row.map(csvCell).join(',')).join('\r\n');}
